    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"Component video is a video signal that has been split into two or more components. In popular use, it refers to a type of analog video information that is transmitted or stored as three separate signals. Component video can be contrasted with composite video (NTSC, PAL or SECAM) in which all the video information is combined into a single line-level signal. Like composite, component video cables do not carry audio and are often paired with audio cables. Here the input is meant.
