    /// <summary>
    ///   <para>conel:DLNA_Ethernet</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"The Digital Living Network Alliance is an international, cross-industry collaboration of consumer electronics, computing industry and mobile device companies. Members of DLNA develop a concept of wired and wireless interoperable networks where digital content such as photos, music, and videos can be shared through consumer electronics (CE), personal computers (PCs), and mobile devices in and beyond the home.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "Digital Living Network Alliance" (http://en.wikipedia.org/wiki/Digital_Living_Network_Alliance) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"DLNA Ethernet"</para></remarks>
