    /// </summary>
    /// <remarks>
    ///   <para>conel:DataFormatImage</para>
    ///   <para>"DPOF (Digital Print Order format) is a format which allows the user of a digital camera or other device such as a Mobile Phone or PDA to define which captured images on the storage card are to be printed, together with information on the number of copies or other image information such as paper size, image title text, image orientation, contact information and more.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "DPOF" (http://en.wikipedia.org/wiki/DPOF) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"DPOF"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DPOF">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DPOF</seealso>
