    /// <summary>
    ///   <para>conel:DV</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:DataFormatVideo</para>
    ///   <para>"Digital Video (DV) is a digital video format created by Sony, JVC, Panasonic and other video camera producers, and launched in 1995. The DV specification (originally known as the Blue Book, current official name IEC 61834) defines both the codec and the tape format.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "DV" (http://en.wikipedia.org/wiki/DV) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"DV"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DV">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DV</seealso>
    let DV = Prefixed_Name(conel, "DV") |> PrefixedName
    /// <summary>
    ///   <para>conel:DVB</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:SignalFormat</para>
    ///   <para>"Digital Video Broadcasting (DVB) is a suite of internationally accepted open standards for digital television. DVB systems distribute data using a variety of approaches, including by satellite (DVB-S, DVB-S2 and DVB-SH; also DVB-SMATV for distribution via SMATV); cable (DVB-C); terrestrial television (DVB-T, DVB-T2) and digital terrestrial television for handhelds (DVB-H,DVB-SH); and via microwave using DTT (DVB-MT), the MMDS (DVB-MC), and/or MVDS standards (DVB-MS).
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "Digital Video Broadcasting" (http://en.wikipedia.org/wiki/Digital_Video_Broadcasting) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"DVB"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVB">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVB</seealso>
    let DVB = Prefixed_Name(conel, "DVB") |> PrefixedName
    /// <summary>
    ///   <para>conel:DVB-T</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:GeneralFeatures</para>
    ///   <para>"DVB-T is an abbreviation for Digital Video Broadcasting - Terrestrial; it is the DVB European-based consortium standard for the broadcast transmission of digital terrestrial television. This system transmits compressed digital audio, video and other data in an MPEG transport stream, using COFDM modulation.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "DVB-T" (http://en.wikipedia.org/wiki/DVB-T) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"DVB-T"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVB-T">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVB-T</seealso>
    let DVB_T = Prefixed_Name(conel, "DVB-T") |> PrefixedName
    /// <summary>
    ///   <para>conel:DVB_COFDM</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:SignalFormat</para>
    ///   <para>"Digital Video Broadcasting (DVB) is a suite of internationally accepted open standards for digital television. Coded OFDM (COFDM) and Discrete multi-tone modulation (DMT) is a frequency-division multiplexing (FDM) scheme utilized as a digital multi-carrier modulation method. A large number of closely-spaced orthogonal sub-carriers are used to carry data. The data is divided into several parallel data streams or channels, one for each sub-carrier. Each sub-carrier is modulated with a conventional modulation scheme (such as quadrature amplitude modulation or phase shift keying) at a low symbol rate, maintaining total data rates similar to conventional single-carrier modulation schemes in the same bandwidth.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "Digital Video Broadcasting" (http://en.wikipedia.org/wiki/Digital_Video_Broadcasting) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"DVB COFDM"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVB_COFDM">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVB_COFDM</seealso>
    let DVB_COFDM = Prefixed_Name(conel, "DVB_COFDM") |> PrefixedName
    /// <summary>
    ///   <para>conel:DVI</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"The Digital Visual Interface (DVI) is a video interface standard designed to maximize the visual quality of digital display devices such as flat panel LCD computer displays and digital projectors. It is designed for carrying uncompressed digital video data to a display. It is partially compatible with the High-Definition Multimedia Interface (HDMI) standard in digital mode (DVI-D), and VGA in analog mode (DVI-A).
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "Digital Visual Interface" (http://en.wikipedia.org/wiki/Digital_Visual_Interface) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"DVI"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVI">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#DVI</seealso>
