    /// <summary>
    ///   <para>conel:DigitalAudioCoaxialOut</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"Digital audio uses digital signals for sound reproduction. This includes analog-to-digital conversion, digital-to-analog conversion, storage and transmission. From the signal point of view, a connector can be viewed as a short, rigid cable. The connector usually has the same impedance as the related cable and probably has a similar cutoff frequency although its dielectric may be different. Some connectors are gold or rhodium plated, while some connectors use nickel or tin plating. Silver is also used due to its excellent conductivity. Although silver tends to oxidize rather quickly, the silver oxide that is produced is still conductive. This may pose a cosmetic issue but it does not degrade the performance of the connector. Here the output is meant.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "Digital audio" (http://en.wikipedia.org/wiki/Digital_audio) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
