    /// <summary>
    ///   <para>conel:HDMI</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"HDMI (High-Definition Multimedia Interface) is a compact audio/video interface for transmitting uncompressed digital data. It represents a digital alternative to consumer analog standards such as Radio Frequency (RF) coaxial cable, composite video, S-Video, SCART, component video, D-Terminal, and VGA. HDMI connects digital audio/video sources such as set-top boxes, Blu-ray Disc players, personal computers (PCs), video game consoles, and AV receivers to compatible digital audio devices, computer monitors, and digital televisions.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "HDMI" (http://en.wikipedia.org/wiki/HDMI) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
