    ///   <para>conel:DataInterfaceType</para>
    ///   <para>"HDMI (High-Definition Multimedia Interface) is a compact audio/video interface for transmitting uncompressed digital data.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "HDMI" (http://en.wikipedia.org/wiki/HDMI) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
