    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "1080i" (http://en.wikipedia.org/wiki/1080i) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
