    /// </summary>
    /// <remarks>
    ///   <para>conel:TVDisplayResolution</para>
    ///   <para>"1080p is the shorthand name for a category of HDTV video modes. The number "1080" represents 1,080 lines of vertical resolution (1080 horizontal scan lines), while the letter p stands for progressive scan (meaning the image is not interlaced). 1080p can be referred to as full HD or full high definition to differentiate it from other HDTV video modes.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "1080p" (http://en.wikipedia.org/wiki/1080p) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
