    ///   <para>"720p is the shorthand name for a category of HDTV video modes. The number 720 stands for the 720 vertical scan lines of display resolution (also known as 720 pixels of vertical resolution), while the letter p stands for progressive scan or non-interlaced.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "720p" (http://en.wikipedia.org/wiki/720p) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
