    /// <summary>
    ///   <para>conel:RF</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"An RF connector is an electrical connector designed to work at radio frequencies in the multi-megahertz range. RF connectors are typically used with coaxial cables and are designed to maintain the shielding that the coaxial design offers. Better models also minimize the change in transmission line impedance at the connection. Mechanically they provide a fastening mechanism (thread, bayonet, braces, push pull) and springs for a low ohmic electric contact while sparing the gold surface thus allowing above 1000 reconnects and reducing the insertion force. Research activity in the area of radio-frequency (RF) circuit design has surged in the last decade in direct response to the enormous market demand for inexpensive, high data rate wireless transceivers.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "RF connector" (http://en.wikipedia.org/wiki/RF_connector) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"RF"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#RF">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#RF</seealso>
    let RF = Prefixed_Name(conel, "RF") |> PrefixedName
    /// <summary>
    ///   <para>conel:RGB</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"The RGB color model is an additive color model in which red, green, and blue light are added together in various ways to reproduce a broad array of colors. The name of the model comes from the initials of the three additive primary colors, red, green, and blue. Typical RGB input devices are color TV and video cameras, image scanners, and digital cameras. Typical RGB output devices are TV sets of various technologies (CRT, LCD, plasma, etc.), computer and mobile phone displays, video projectors, multicolor LED displays, and large screens as JumboTron, etc. Color printers, on the other hand, are usually not RGB devices, but subtractive color devices (typically CMYK color model).
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "RGB" (http://en.wikipedia.org/wiki/RGB) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"RGB"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#RGB">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#RGB</seealso>
    let RGB = Prefixed_Name(conel, "RGB") |> PrefixedName
    /// <summary>
    ///   <para>conel:RISC</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:ProcessorType</para>
    ///   <para>"Reduced instruction set computing, represents a CPU design strategy emphasizing the insight that simplified instructions that "do less" may still provide for higher performance if this simplicity can be utilized to make instructions execute very quickly."</para>
