    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#RISC">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#RISC</seealso>
    let RISC = Prefixed_Name(conel, "RISC") |> PrefixedName
    /// <summary>
