    ///   <para>conel:Connectivity</para>
    ///   <para>"In telecommunications, RS-232 (Recommended Standard 232) is a standard for serial binary data signals connecting between a DTE (Data Terminal Equipment) and a DCE (Data Circuit-terminating Equipment). It is commonly used in computer serial ports.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "RS-232" (http://en.wikipedia.org/wiki/RS-232) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"RS-232"</para></remarks>
