    /// <remarks>
    ///   <para>conel:Connectivity</para>
    ///   <para>"SCART (from Syndicat des Constructeurs d'Appareils Radiorécepteurs et Téléviseurs, Radio and Television Receiver Manufacturer's Association) is a French-originated standard and associated 21-pin connector for connecting audio-visual (AV) equipment together.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "SCART" (http://en.wikipedia.org/wiki/SCART) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
