    /// <summary>
    ///   <para>conel:SDHC</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:StorageMedia</para>
    ///   <para>"SDHC (Secure Digital High Capacity, SD 2.0) is an extension of the SD standard that appeared in June 2006.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "Secure Digital card" (http://en.wikipedia.org/wiki/Secure_Digital_card) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"SDHC"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SDHC">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SDHC</seealso>
    let SDHC = Prefixed_Name(conel, "SDHC") |> PrefixedName
    /// <summary>
    ///   <para>conel:SDTV_480i</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:TVDisplayResolution</para>
    ///   <para>"480i is the shorthand name for a video mode, namely the U.S. NTSC television system or digital television systems with the same characteristics. The i, which is sometimes uppercase, stands for interlaced, the 480 for a vertical frame resolution of 480 lines containing picture information; while NTSC has a total of 525 lines, only 480 of these are used to display the image.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "480i" (http://en.wikipedia.org/wiki/480i) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"SDTV 480i"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SDTV_480i">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SDTV_480i</seealso>
    let SDTV_480i = Prefixed_Name(conel, "SDTV_480i") |> PrefixedName
    /// <summary>
    ///   <para>conel:SDTV_576i</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:TVDisplayResolution</para>
    ///   <para>"576i is a standard-definition video mode used in (former) PAL and SECAM countries. In digital applications it's usually referred to as "576i", in analogue contexts it's often quoted as "625 lines". The 576 identifies a vertical resolution of 576 lines (usually with a horizontal resolution of 720 or 704 pixels), and the i identifies it as an interlaced resolution.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "576ii" (http://en.wikipedia.org/wiki/576i) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"SDTV 576i"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SDTV_576i">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SDTV_576i</seealso>
    let SDTV_576i = Prefixed_Name(conel, "SDTV_576i") |> PrefixedName
    /// <summary>
    ///   <para>conel:SECAM</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:SignalFormat</para>
    ///   <para>"SECAM, also written SÉCAM (Séquentiel couleur à mémoire, French for "Sequential Color with Memory"), is an analog color television system first used in France.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "SECAM" (http://en.wikipedia.org/wiki/SECAM) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
