    /// <summary>
    ///   <para>conel:SECAM-B_G</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:SignalFormat</para>
    ///   <para>"SECAM, also written SÉCAM (Séquentiel couleur à mémoire, French for "Sequential Color with Memory"), is an analog color television system first used in France. SECAM-B/G is used in the Middle East, former East Germany and Greece.
    ///
    /// (This description is partly based on or reuses content from the Wikipedia article "SECAM" (http://en.wikipedia.org/wiki/SECAM) and is licensed under the GNU Free Documentation License (http://www.gnu.org/copyleft/fdl.html).)"</para>
    /// labels<para>"SECAM-B G"</para></remarks>
    /// <seealso href="http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SECAM-B_G">http://www.ebusiness-unibw.org/ontologies/consumerelectronics/v1#SECAM-B_G</seealso>
    let SECAM_B_G = Prefixed_Name(conel, "SECAM-B_G") |> PrefixedName
    /// <summary>
    ///   <para>conel:SECAM-D_K</para>
    /// </summary>
    /// <remarks>
    ///   <para>conel:SignalFormat</para>
